import{_ as e,C as o,o as r,c as i,j as d,a as n,G as s,a3 as l}from"./chunks/framework.exbasbhr.js";const x=JSON.parse('{"title":"安装与更新通道","description":"ICC-CE 的系统要求、安装版与绿色版的区别、四个更新通道的含义","frontmatter":{"title":"安装与更新通道","description":"ICC-CE 的系统要求、安装版与绿色版的区别、四个更新通道的含义"},"headers":[],"relativePath":"cn/guide/installation.md","filePath":"cn/guide/installation.md"}'),c={name:"cn/guide/installation.md"};function h(b,t,g,p,u,m){const a=o("ArticleMetadata");return r(),i("div",null,[t[0]||(t[0]=d("h1",{id:"安装与更新通道",tabindex:"-1"},[n("安装与更新通道 "),d("a",{class:"header-anchor",href:"#安装与更新通道","aria-label":'Permalink to "安装与更新通道"'},"​")],-1)),s(a),t[1]||(t[1]=l('<h2 id="系统要求" tabindex="-1">系统要求 <a class="header-anchor" href="#系统要求" aria-label="Permalink to &quot;系统要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>操作系统</td><td>Windows 10 版本 1809（build 17763）及以上、Windows 11</td></tr><tr><td>运行时</td><td><strong>.NET 6 桌面运行时</strong>（<code>net6.0-windows10.0.19041.0</code>）</td></tr><tr><td>内存</td><td>建议 4GB 以上</td></tr><tr><td>显卡</td><td>支持 Direct3D 11 的显卡可启用硬件加速墨迹渲染</td></tr><tr><td>输入设备</td><td>触摸屏 / 数位板 / 鼠标均可，触控设备体验最佳</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关于 .NET 版本</p><p>主程序运行在 <strong>.NET 6</strong> 上，不是 .NET Framework 4.x。安装版会在需要时提示安装运行时； 绿色版若无法启动，多半是缺少 .NET 6 桌面运行时，请到微软官网下载 “.NET Desktop Runtime 6.x” 的 x64 或 x86 版本。</p><p>例外：手写识别所依赖的 IACore 组件只有 32 位版本，程序会额外启动一个 .NET Framework 4.7.2 的辅助进程来调用它。 这部分由安装包处理，通常无需手动干预。</p></div><h2 id="安装版还是绿色版" tabindex="-1">安装版还是绿色版 <a class="header-anchor" href="#安装版还是绿色版" aria-label="Permalink to &quot;安装版还是绿色版&quot;">​</a></h2><p>发布页同时提供两种形态，功能完全一致：</p><table tabindex="0"><thead><tr><th></th><th>安装版（<code>.exe</code>）</th><th>绿色版（<code>.zip</code>）</th></tr></thead><tbody><tr><td>安装方式</td><td>运行安装向导</td><td>解压到任意目录</td></tr><tr><td>开始菜单/桌面快捷方式</td><td>自动创建</td><td>需手动创建</td></tr><tr><td>卸载</td><td>控制面板卸载</td><td>直接删除文件夹</td></tr><tr><td>写入系统</td><td>是（安装目录、注册表卸载项）</td><td>否</td></tr><tr><td>适用场景</td><td>个人电脑、长期使用</td><td>U 盘便携、机房批量部署、多版本并存</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">推荐</p><p>班级一体机等长期使用的设备建议用<strong>安装版</strong>；需要在多台机器间携带、或想同时保留多个版本时用<strong>绿色版</strong>。</p></div><h2 id="位数选择-32-位-64-位" tabindex="-1">位数选择（32 位 / 64 位） <a class="header-anchor" href="#位数选择-32-位-64-位" aria-label="Permalink to &quot;位数选择（32 位 / 64 位）&quot;">​</a></h2><ul><li>现代设备一律选 <strong>64 位（x64）</strong></li><li>仅在系统为 32 位、或需要与 32 位 Office 深度联动时选 <strong>32 位（x86）</strong></li></ul><p>不确定时按 <kbd>Win</kbd> + <kbd>Pause</kbd> 查看“系统类型”。</p><h2 id="四个更新通道" tabindex="-1">四个更新通道 <a class="header-anchor" href="#四个更新通道" aria-label="Permalink to &quot;四个更新通道&quot;">​</a></h2><p>下载页的通道切换对应四类不同的构建来源：</p><table tabindex="0"><thead><tr><th>通道</th><th>来源</th><th>包含 pre-release</th><th>说明</th></tr></thead><tbody><tr><td><strong>Beta</strong>（推荐）</td><td><code>community-beta</code> 仓库</td><td>✅</td><td>更新最快、修复最及时，日常使用首选</td></tr><tr><td><strong>Preview</strong></td><td><code>community-beta</code> 仓库</td><td>❌</td><td>比 Beta 收敛，想尝鲜又偏好稳定时选它</td></tr><tr><td><strong>正式版</strong></td><td><code>community</code> 主仓库</td><td>❌</td><td>发布频率最低，稳定性要求极高时选它</td></tr><tr><td><strong>Nightly</strong></td><td>GitHub Actions 构建产物</td><td>—</td><td><strong>未经测试的 Debug 构建</strong></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Nightly 构建</p><p>Nightly 是 CI 从 <code>net6</code> 分支最新提交自动产出的 <strong>Debug</strong> 版本，没有经过任何测试，可能包含严重缺陷、崩溃或数据丢失风险。 <strong>请勿在正式课堂环境使用。</strong> 下载页会强制你阅读风险说明并勾选确认后才允许下载。</p></div><h3 id="为什么-beta-通道的安装版来自主仓库" tabindex="-1">为什么 Beta 通道的安装版来自主仓库 <a class="header-anchor" href="#为什么-beta-通道的安装版来自主仓库" aria-label="Permalink to &quot;为什么 Beta 通道的安装版来自主仓库&quot;">​</a></h3><p><code>community-beta</code> 仓库只发布绿色版 zip。下载页在该通道下找不到安装版时，会按<strong>相同的版本 tag</strong> 回到主仓库 <code>community</code> 取对应的安装版，并在按钮上标注「主仓库」。两者版本号一致，可放心使用。</p><h2 id="下载加速" tabindex="-1">下载加速 <a class="header-anchor" href="#下载加速" aria-label="Permalink to &quot;下载加速&quot;">​</a></h2><p>下载页启动时会并发探测两类线路，并在页面顶部显示结果：</p><ul><li><strong>智教联盟镜像</strong>：国内直连速度较好，仅提供绿色版 zip。点击下载前还会再校验一次文件是否真的存在，不存在则自动回退</li><li><strong>GitHub 加速镜像</strong>：六个候选节点竞速，取最快的一个用于安装版与 API 请求；全部不可用时回退到 GitHub 官方直连</li></ul><p>Nightly 的产物托管在 <code>nightly.link</code>，只能使用页面上列出的几个加速节点，可手动切换，选择会被记住。</p><h2 id="升级" tabindex="-1">升级 <a class="header-anchor" href="#升级" aria-label="Permalink to &quot;升级&quot;">​</a></h2><p>ICC-CE 内置在线更新检查，在设置中可配置检查频率与更新通道。手动升级时：</p><ul><li><strong>安装版</strong>：直接运行新版本安装包覆盖安装即可，配置与墨迹保留</li><li><strong>绿色版</strong>：解压新版本到新目录，然后把旧目录下的配置文件与 <code>Saves</code> 文件夹复制过去</li></ul><p>具体的数据目录位置见<a href="/website/cn/guide/files-and-data">配置文件与数据目录</a>。</p><div class="warning custom-block"><p class="custom-block-title">跨通道切换</p><p>从 Beta 回退到正式版时，可能出现新版本写入的配置项无法被旧版本识别的情况。 如遇异常，请备份后删除配置文件让程序重新生成。</p></div><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><ul><li><strong>安装版</strong>：设置 → 应用 → 已安装的应用 → InkCanvasForClass CE → 卸载</li><li><strong>绿色版</strong>：直接删除整个文件夹</li></ul><p>卸载不会自动清除用户配置与墨迹存档，需要彻底清理时请手动删除数据目录。</p>',28))])}const f=e(c,[["render",h]]);export{x as __pageData,f as default};
